function pickUnifiedStoryWinner() {
  applyNaturalArcStreetUnlock?.();
  applyNaturalAntennaAdvance?.();
  applyColdYieldFlags?.();
  syncColdYieldBodyClass?.();

  const day = state.save.dayIndex || 1;
  const yielded = (typeof coldShouldYield === "function") ? coldShouldYield() : (day >= 7 || storyFlag("cold_day2_yielded"));

  // 1) Cold only if NOT yielded
  if (!yielded && typeof coldPropStillWins === "function" ? coldPropStillWins() : (day >= 2 && day < 7 && ["cold_open_mediate","cold_open_instigate","cold_open_stage"].some(storyFlag))) {
    const html = day2StreetStageHtml();
    if (html) return { id: "cold_day2_prop", html, npc: "", suppressBanner: true, suppressSpotlight: true };
  }

  // 2) Ledger natural (day≥10 / wins flag) before volume if tenure done
  if (day >= 10 || storyFlag("natural_ledger_street_wins")) {
    const led = (storyForm14?.()?.naturalStreetPropsHard || storyForm13?.()?.naturalStreetPropsYield || [])
      .find((p) => p.testId === "story-street-ledger-tray");
    const html = led ? (state.locale === "tr" && led.htmlTr ? led.htmlTr : led.html) : "";
    if (html) {
      state.save.storyFlags.natural_ledger_street = true;
      return { id: "ledger_natural", html, npc: "", suppressBanner: true, suppressSpotlight: true };
    }
  }

  // 3) Volume natural headphones — calendar or antenna gate
  if (yielded || day >= 7 || (day >= 3 && ["arc_kite_antenna_complete","quest_antenna_complete","natural_antenna_complete","arc_kite_antenna_beat4","flag_fence_and_kite","flag_kite_chaos_buff"].some(storyFlag))) {
    const vol = (storyForm14?.()?.naturalStreetPropsHard || storyForm13?.()?.naturalStreetPropsYield || storyForm12?.()?.naturalStreetProps || [])
      .find((p) => p.testId === "story-street-headphones-note");
    const html = vol ? (state.locale === "tr" && vol.htmlTr ? vol.htmlTr : vol.html) : "";
    if (html) {
      state.save.storyFlags.natural_volume_street = true;
      state.save.storyFlags.cold_day2_yielded = true;
      return { id: "volume_natural", html, npc: "", suppressBanner: true, suppressSpotlight: true };
    }
  }

  // 4) Fall through prior handoff / beat props (form10/11) if any
  return null;
}

function syncColdYieldBodyClass() {
  const day = state.save.dayIndex || 1;
  const y = (typeof coldShouldYield === "function") ? coldShouldYield() : day >= 7;
  document.body.classList.toggle("rp-cold-yielded", !!y);
  document.body.dataset.dayIndex = String(day);
}

